UPDATE om_simulation_page_tbl 
SET page_coll_status = #{page_coll_status}
WHERE page_no = #{page_no}

UPDATE om_simulation_page_tbl 
SET page_opt_status = #{page_opt_status}
WHERE page_no = #{page_no}

UPDATE om_simulation_page_tbl 
SET updt_dt = now() 

		, org_score = #{org_score}


		, new_score = #{new_score}


		, org_time = #{org_time}


		, new_time = #{new_time}

WHERE page_no = #{page_no}

UPDATE om_simulation_page_tbl 
SET is_complete = 1
WHERE page_url = #{page_url}
